[$html]=render('articles',['page'=>'2']);@$doc->loadHTML('<?xml encoding="utf-8" ?>'.$html);$xp=new DOMXPath($doc);check($xp->query('//div[contains(@class,"f-results-grid")]/article')->length===4,'eight per page; second page has four');
[$html]=render('articles',['category'=>'city']);check(str_contains($html,'Город между кадрами')&&!str_contains($html,'href="/focus/shoreline/"'),'direction filter');
[$html]=render('articles',['year'=>'1900']);check(str_contains($html,'Истории ещё впереди')&&str_contains($html,'<option selected>1900</option>'),'empty period retains exact year');
[$html]=render('articles',['archive'=>'1']);check(str_contains($html,'name="archive" value="1"')&&str_contains($html,'archive=1'),'archive context retained');
[$html]=render('category/city');check(!str_contains($html,'name="category"'),'no conflicting category filter inside direction');
[$html]=render('search',['q'=>'берег']);check(str_contains($html,'<mark>')&&str_contains($html,'shoreline'),'actual search and highlight');[$html]=render('search',['q'=>'NO_MATCH_XYZ']);check(str_contains($html,'Ничего не нашлось')&&!str_contains($html,'f-tile-image'),'empty search');
foreach(['q','category','year','month','sort','page']as $key){[$html,$status]=render('search',[$key=>['bad']]);check($status===400&&str_contains($html,'role="alert"'),'malformed filter '.$key);}
foreach([['month'=>'13'],['year'=>'hello']]as $query){[$html,$status]=render('articles',$query);check($status===400&&str_contains($html,'корректные год'),'invalid period');}
$one=$seed['pages'][0];$one['cover']='';$one['blocks']=[];[$html]=render('',[],[$one]);check(str_contains($html,'f-hero-empty')&&!str_contains($html,'frame-1.jpg'),'missing cover never fabricates a photo');[$html]=render('',[],[]);check(str_contains($html,'Место для')&&!str_contains($html,'f-hero-photo'),'empty publication');
$draft=$one;$draft['status']='draft';[$html,$status]=render($draft['slug'],[],[$draft]);check($status===404,'draft private');[$html,$status]=render($draft['slug'],[],[$draft],true,'private-proof');check($status===200&&str_contains($html,'snapshot=private-proof'),'preview preserves session snapshot in links');
$future=$one;$future['published_at']=gmdate('Y-m-d H:i:s',time()+86400);[$html,$status]=render($future['slug'],[],[$future]);check($status===404,'future publication private');$due=$one;$due['status']='scheduled';$due['published_at']='2020-01-01 12:00:00';[$html,$status]=render($due['slug'],[],[$due]);check($status===200,'schedule appears when due');
