[$html]=render('articles',['vitals'=>'1']);check(str_contains($html,'web-vitals.iife.js'),'opt-in diagnostics');[$html]=render('articles');check(!str_contains($html,'web-vitals.iife.js'),'no visitor telemetry by default');
